begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) values('b3100000-0000-4000-8000-000000000800','synthetic-diagnostic-staff@example.test','{}'),('b3100000-0000-4000-8000-000000000801','synthetic-diagnostic-dvm@example.test','{}'),('b3100000-0000-4000-8000-000000000802','synthetic-diagnostic-admin@example.test','{}');
update profiles set is_active=true,full_name='Synthetic diagnostic reviewer' where id::text like 'b3100000-%';
insert into user_roles(user_id,role) values('b3100000-0000-4000-8000-000000000800','STAFF'),('b3100000-0000-4000-8000-000000000801','DVM'),('b3100000-0000-4000-8000-000000000802','ADMIN');
create temp table fx(k text primary key,id uuid);grant all on fx to authenticated;
create temp table data(k text primary key,v jsonb);grant all on data to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000800","role":"authenticated"}',true);
insert into fx select 'client',id from save_client(auth.uid(),null,null,'Synthetic','Diagnostics','+13035550188','synthetic-diagnostics@example.test','EMAIL',null,null);
insert into fx select 'pet',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic diagnostics dog','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into fx select 'sibling',id from save_patient(null,(select id from fx where k='client'),null,'Synthetic diagnostics sibling','Dog',null,null,'unknown',null,'unknown','unknown',null,null,null);
insert into data values('values','{"panel_name":"Synthetic chemistry","category":"laboratory","collected_on":"2026-10-01","reported_on":"2026-10-02","specimen":"Serum","method":"Synthetic device","source":"Manual in-house","interpretation":"Synthetic documentary findings","lab_order_id":null,"lab_order_version":null,"encounter_id":null,"encounter_version":null,"document_id":null,"document_version":null,"observations":[{"id":"b3100000-0000-4000-8000-000000000001","analyte_key":"synthetic-alt","label":"ALT","kind":"numeric","value_number":0,"value_text":null,"unit":"U/L","reference_low":1,"reference_high":100,"reference_text":"As entered","source_flag":"Recorded flag"},{"id":"b3100000-0000-4000-8000-000000000002","analyte_key":"synthetic-screen","label":"Screen","kind":"qualitative","value_number":null,"value_text":"Not detected","unit":null,"reference_low":null,"reference_high":null,"reference_text":"As reported","source_flag":""}]}');
insert into data select 'draft',save_diagnostic_panel('b3100000-0000-4000-8000-000000000050','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),null,'draft',(select v from data where k='values'));
select is((select v#>>'{panel,version}' from data where k='draft'),'1','New panel begins at version one');
select is((select v#>>'{panel,created_by}' from data where k='draft'),auth.uid()::text,'Actor is server stamped');
select is((select v#>>'{panel,draft,observations,0,value_number}' from data where k='draft'),'0','Zero stays a real numeric result');
select is(save_diagnostic_panel('b3100000-0000-4000-8000-000000000050','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),null,'draft',(select v from data where k='values')),(select v from data where k='draft'),'Exact lost-response retry returns original receipt');
select is(read_diagnostic_action('b3100000-0000-4000-8000-000000000050','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),null,'draft',(select v from data where k='values'),'',''),(select v from data where k='draft'),'Read-only recovery returns exact receipt');
select throws_ok($$select save_diagnostic_panel('b3100000-0000-4000-8000-000000000050','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),null,'draft',(select v||'{"panel_name":"Changed retry"}' from data where k='values'))$$,'23505','Diagnostic action conflicts with saved work','Changed retry cannot reuse action ID');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),'b3100000-0000-4000-8000-000000000100',(select id from fx where k='sibling'),1,'draft',(select v from data where k='values'))$$,'42501','Diagnostic panel belongs to another patient','Wrong patient cannot mutate panel');
select is(read_diagnostic_panel('b3100000-0000-4000-8000-000000000100',(select id from fx where k='sibling')),null::jsonb,'Wrong-patient read does not reveal panel');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),'b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),7,'draft',(select v from data where k='values'))$$,'PT409','Diagnostic panel changed; reload before resolving your draft','Stale draft rejects permanently');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),'b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),1,'finalize',(select v from data where k='values'),'Synthetic review')$$,'42501','Active named veterinarian required for clinical review','Ordinary staff cannot finalize');
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000802","role":"authenticated"}',true);
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),'b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),1,'finalize',(select v from data where k='values'),'Synthetic review')$$,'42501','Active named veterinarian required for clinical review','Administrator is not clinical reviewer');
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000801","role":"authenticated"}',true);
insert into data select 'final',save_diagnostic_panel('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),1,'finalize',(select v from data where k='values'),'Synthetic exact review');
select is((select v#>>'{current,reviewed_by}' from data where k='final'),auth.uid()::text,'Named DVM is attributed');
select is((select v#>>'{current,entered_by}' from data where k='final'),'b3100000-0000-4000-8000-000000000800','Original entering staff identity is retained');
select is((select v#>>'{current,number}' from data where k='final'),'1','First reviewed version is immutable version one');
select is((select v#>>'{export_eligible}' from data where k='final'),'false','No PDF or release commissioning is fabricated');
select is((select v#>>'{panel,draft}' from data where k='final'),null::text,'Finalized draft is cleared');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),'b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),2,'finalize',(select v from data where k='values'),'Synthetic repeated finalize')$$,'PT409','Finalize only the exact saved diagnostic draft','Finalization requires a saved exact draft');
insert into data select 'census',list_diagnostic_trends((select id from fx where k='pet'),null,1,null);
select is(jsonb_array_length((select v->'items' from data where k='census')),1,'Only current finalized versions appear in trend census');
insert into data select 'corrected_values',jsonb_set(v,'{observations,0,value_number}','2') from data where k='values';
select save_diagnostic_panel('b3100000-0000-4000-8000-000000000052','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),2,'draft',(select v from data where k='corrected_values'));
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),'b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),3,'finalize',(select v from data where k='corrected_values'),'Synthetic correction review')$$,'23514','Explicit exact review and correction reason required','Correction reason cannot be omitted');
insert into data select 'corrected',save_diagnostic_panel('b3100000-0000-4000-8000-000000000053','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),3,'finalize',(select v from data where k='corrected_values'),'Synthetic correction review','Corrected source transcription');
select is((select v#>>'{current,number}' from data where k='corrected'),'2','Correction appends version two');
select is(list_diagnostic_history('b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),2,1)#>>'{items,0,snapshot,observations,0,value_number}','0','Historical zero remains unchanged after correction');
select is(list_diagnostic_history('b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),null,1)->>'next','2','Bounded history exposes older page');
select throws_ok($$select list_diagnostic_trends((select id from fx where k='pet'),null,1,(select v->>'census_hash' from data where k='census'))$$,'PT409','Diagnostic trend census changed; reload the complete series','Paged trend correction cannot mix census versions');
select lives_ok($$select save_diagnostic_panel('b3100000-0000-4000-8000-000000000051','b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'),1,'finalize',(select v from data where k='values'),'Synthetic exact review')$$,'Old exact confirmation receipt recovers after later correction');
select throws_ok($$select * from diagnostic_panel_versions$$,'42501',null,'Staff cannot read private ledger directly');
select throws_ok($$select diagnostic_detail('b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'))$$,'42501',null,'Private detail core is not an API endpoint');
select throws_ok($$select list_diagnostic_panels((select id from fx where k='pet'),null,null)$$,'23514','Bounded diagnostic cursor required','Null limit does not disable bounds');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,'draft',(select jsonb_set(v,'{observations,0,value_number}','null') from data where k='values'))$$,'23514','Numeric finding requires finite number and explicit original unit','Blank numeric result cannot become zero');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,'draft',(select jsonb_set(v,'{observations,1,reference_low}','0') from data where k='values'))$$,'23514','Qualitative finding requires text without numeric fields','Text finding cannot become numeric');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,'draft',(select v||'{"created_by":"b3100000-0000-4000-8000-000000000800"}' from data where k='values'))$$,'23514','Bounded complete diagnostic fields required','Actor cannot be forged in input');
select throws_ok($$select save_diagnostic_panel(gen_random_uuid(),gen_random_uuid(),(select id from fx where k='pet'),null,'draft',(select jsonb_set(v,'{observations,0,value_number}','1e-200') from data where k='values'))$$,'23514','Diagnostic value exceeds numeric capacity','Tiny nonzero finding is rejected before JSON clients round it to zero');
reset role;
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000801","role":"authenticated"}',true);
select ok(exists(select 1 from jsonb_array_elements(record_request_inventory((select id from fx where k='pet'))->'exclusions') x where x->>'family'='diagnostic_panel_ids'),'Complete release census visibly excludes unsupported diagnostic PDFs');
update profiles set full_name='Changed current profile display name' where id='b3100000-0000-4000-8000-000000000801';
select is(read_diagnostic_panel('b3100000-0000-4000-8000-000000000100',(select id from fx where k='pet'))#>>'{current,reviewer_name}','Synthetic diagnostic reviewer','Historical reviewer name is frozen despite a later profile edit');
select throws_ok($$update diagnostic_panel_versions set snapshot='{}' where id='b3100000-0000-4000-8000-000000000051'$$,'23514','Diagnostic evidence is immutable','Privileged edits cannot overwrite finalized evidence');
select throws_ok($$delete from diagnostic_panel_actions where id='b3100000-0000-4000-8000-000000000050'$$,'23514','Diagnostic evidence is immutable','Saved action receipt cannot be deleted');
select is((select count(*)::integer from diagnostic_panel_revisions where panel_id='b3100000-0000-4000-8000-000000000100'),4,'Each real mutation has one audit revision; retries do not duplicate');
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000802","role":"authenticated"}',true);
update profiles set is_active=false where id='b3100000-0000-4000-8000-000000000801';
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"b3100000-0000-4000-8000-000000000801","role":"authenticated"}',true);
select throws_ok($$select list_diagnostic_panels((select id from fx where k='pet'))$$,'42501','Active staff access required','Offboarded reviewer cannot read workflow');
reset role;set local role anon;
select throws_ok($$select list_diagnostic_panels(gen_random_uuid())$$,'42501',null,'Anonymous cannot read diagnostics');
reset role;set local role service_role;
select throws_ok($$select list_diagnostic_panels(gen_random_uuid())$$,'42501',null,'Service role cannot make staff decisions');
reset role;select * from finish();rollback;
